// === Laporan Keuangan Bulanan ===
// Menghitung total pendapatan, pengeluaran, laba kotor, laba bersih, pajak

const namaBulan = [
  'Januari', 'Februari', 'Maret', 'April', 'Mei', 'Juni',
  'Juli', 'Agustus', 'September', 'Oktober', 'November', 'Desember'
];

const now = new Date();
const bulanLalu = new Date(now.getFullYear(), now.getMonth() - 1, 1);
const bulan = namaBulan[bulanLalu.getMonth()];
const tahun = bulanLalu.getFullYear();
const periode = `${bulan} ${tahun}`;

// Data pendapatan dari node sebelumnya
const pendapatanData = $input.all().filter(i => i.json._sheet === 'Pendapatan' || i.json.Kategori);
const pengeluaranData = $input.all().filter(i => i.json._sheet === 'Pengeluaran' || i.json.JenisBiaya);

// Kategori Pendapatan
const kategoriPendapatan = {};
let totalPendapatan = 0;
for (const row of pendapatanData) {
  const kategori = row.json.Kategori || 'Lainnya';
  const jumlah = parseFloat(row.json.Jumlah) || 0;
  kategoriPendapatan[kategori] = (kategoriPendapatan[kategori] || 0) + jumlah;
  totalPendapatan += jumlah;
}

// Kategori Pengeluaran
const kategoriPengeluaran = {};
let totalPengeluaran = 0;
for (const row of pengeluaranData) {
  const kategori = row.json.JenisBiaya || row.json.Kategori || 'Lainnya';
  const jumlah = parseFloat(row.json.Jumlah) || 0;
  kategoriPengeluaran[kategori] = (kategoriPengeluaran[kategori] || 0) + jumlah;
  totalPengeluaran += jumlah;
}

// Hitung HPP (Harga Pokok Penjualan) dari kategori terkait
const hpp = (kategoriPengeluaran['HPP'] || 0) + (kategoriPengeluaran['Bahan Baku'] || 0);

// Beban Operasional
const bebanOperasional = (kategoriPengeluaran['Gaji'] || 0)
  + (kategoriPengeluaran['Sewa'] || 0)
  + (kategoriPengeluaran['Listrik/Air'] || 0)
  + (kategoriPengeluaran['Marketing'] || 0)
  + (kategoriPengeluaran['Operasional'] || 0);

// Perhitungan Laba
const labaKotor = totalPendapatan - hpp;
const labaBersihSebelumPajak = labaKotor - bebanOperasional;
const tarifPajak = 0.22; // PPh Badan 22%
const pajak = Math.max(0, labaBersihSebelumPajak * tarifPajak);
const labaBersih = labaBersihSebelumPajak - pajak;

// Format Rupiah
const formatRupiah = (angka) => {
  return 'Rp ' + angka.toLocaleString('id-ID', { minimumFractionDigits: 0, maximumFractionDigits: 0 });
};

// Breakdown per kategori untuk laporan
const breakdownPendapatan = Object.entries(kategoriPendapatan)
  .map(([k, v]) => `  - ${k}: ${formatRupiah(v)}`).join('\n');
const breakdownPengeluaran = Object.entries(kategoriPengeluaran)
  .map(([k, v]) => `  - ${k}: ${formatRupiah(v)}`).join('\n');

// Margin
const marginKotor = totalPendapatan > 0 ? ((labaKotor / totalPendapatan) * 100).toFixed(1) : '0.0';
const marginBersih = totalPendapatan > 0 ? ((labaBersih / totalPendapatan) * 100).toFixed(1) : '0.0';

return {
  json: {
    periode,
    bulan,
    tahun,
    totalPendapatan,
    totalPengeluaran,
    hpp,
    labaKotor,
    bebanOperasional,
    labaBersihSebelumPajak,
    pajak,
    labaBersih,
    marginKotor: `${marginKotor}%`,
    marginBersih: `${marginBersih}%`,
    totalPendapatanFormatted: formatRupiah(totalPendapatan),
    totalPengeluaranFormatted: formatRupiah(totalPengeluaran),
    hppFormatted: formatRupiah(hpp),
    labaKotorFormatted: formatRupiah(labaKotor),
    bebanOperasionalFormatted: formatRupiah(bebanOperasional),
    pajakFormatted: formatRupiah(pajak),
    labaBersihFormatted: formatRupiah(labaBersih),
    breakdownPendapatan,
    breakdownPengeluaran,
    kategoriPendapatan,
    kategoriPengeluaran,
    tanggalLaporan: now.toISOString().split('T')[0]
  }
};

